import java.util.*;
public class Driver { static String filter(List<String> logs,String word){StringBuilder b=new StringBuilder();int n=0;for(String line:logs){String[] p=line.split(" ",3);if(p.length==3&&p[2].toLowerCase().contains(word.toLowerCase())){n++;b.append(p[0]).append(' ').append(p[1]).append(": ").append(p[2]).append('\n');}}return "Matches: "+n+"\n"+b.toString().trim();}public static void main(String[]a){String word="Hello";System.out.println("Enter Keyword: "+word);System.out.println(filter(List.of("10:05 alice Hello there","10:10 bob Good Morning","WrongLine","10:20 john Hello Manav","10:30 david Bye"),word));}}
